INSERT INTO public.syrups (id, title, description, ingredients, instructions, yield_ml, storage, validity, imageurl) VALUES
(2, 'Xarope de Açafrão', '', '[{"name":"Açúcar","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Açafrão","amount":"1/4","unit":"colher de sopa","note":""}]', '["Método: Infusão"," Junte todos os ingredientes em uma panela pequena, e coloque em fogo médio, mexendo até que o açúcar se dissolva por completo. Assim que levantar fervura, desligue o fogo e deixe a mistura esfriar. Com um tea strainer, coe com auxílio de um funil para uma garrafa."]', '250', 'Refrigeração', '1 mês', '/uploads/syrups/xarope-alcafrao.png'),
(3, 'Xarope de Abacaxi', '', '[{"name":"Abacaxi médio","amount":"1","unit":"unidade","note":""},{"name":"Açúcar","amount":"960","unit":"g","note":""},{"name":"Água","amount":"480","unit":"ml","note":""}]', '["Método: Maceração","Em um recipiente adicione a água e o açúcar e mexa até dissolver. Corte o abacaxi em cubos e acrescente à mistura. Deixe tudo descansando por 24 horas. Tire os cubos de abacaxi e reserve-os. Com um espremedor, extraia o suco dos cubos de abacaxi e adicione à mistura. Mexa até dissolver possíveis grãos de açúcar residuais. Com um tea strainer, coe com auxilio de um funil para uma garrafa. Adicione um dash de vodka para conservar. "]', '600', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-abacaxi.jpg'),
(4, 'Xarope de Acerola', '', '[{"name":"Acerola","amount":"300","unit":"g","note":""},{"name":"Açúcar","amount":"250","unit":"g","note":""},{"name":"Água","amount":"180","unit":"ml","note":""}]', '["Numa panela colocar a acerola e macerar, em fogo médio, em outra panela acrescentar as acerolas, incorporar o açúcar, mexer um pouco com uma colher de pau, e acrescentar a água.","Agora mexer bem, até o açúcar diluir, e deixar por 10 minutos no fogo. Esperar esfriar e depois coar num recipiente utilizando uma peneira fina e depois num filtro de café."]', '200', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-acerola.jpg'),
(5, 'Xarope de Açúcar Demerara', '', '[{"name":"Açúcar Demerara","amount":"1","unit":"xícara","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""}]', '["Em uma panela, adicione parte iguais de água e demerara, em fogo médio, mexendo devagar, até que o açúcar se dissolva por completo, tornando o líquido transparente. Sua tonalidade e textura são semelhantes às do caramelo. Quando levantar fervura, desligue o fogo e deixe a mistura esfriar, coando com uma peneira fina e a ajuda de um funil para uma garrafa. Tampe e guarde na geladeira. Dura até duas semanas. Controle a validade etiquetando seu xarope com a data de produção."]', '200', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-demerara1.jpg'),
(6, 'Xarope de Açúcar Mascavo', '', '[{"name":"Açúcar Mascavo","amount":"1","unit":"xícara","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""}]', '["Misture o açúcar mascavo e a água e misture numa panela em fogo médio até que o açúcar se dissolva por inteiro, desligue o fogo e deixe esfriar. Coe com auxílio de uma peneira e um funil para uma garrafa e tampe. Guarde sob refrigeração por até duas semanas. Etiquete com a data de produção."]', '250', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-mascavo.jpg'),
(7, 'Xarope de Aipo', '', '[{"name":"Aipo Picado","amount":"240","unit":"g","note":""},{"name":"Açúcar","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""}]', '[" Em uma panela, junte todos os ingredientes e leve ao fogo médio, sempre mexendo. Após o ponto de fervura, cozinhe a mistura por 5 minutos. Em seguida, retire do fogo e deixe esfriar. Com um tea strainer e um funil, coe para uma garrafa."]', '250', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-aipo.jpg'),
(8, 'Xarope de Alfazema', '', '[{"name":"Alfazema Culinária","amount":"2","unit":"colheres","note":"colheres de sopa"},{"name":"Açúcar","amount":"180","unit":"g","note":""},{"name":"Água","amount":"180","unit":"ml","note":""}]', '["Método: infusão","Junte todos os ingredientes em uma panela e aqueça sob fogo médio, mexendo para dissolver o açúcar até o ponto de fervura. Desligue o fogo e deixe esfriar até a temperatura ambiente. Com um tea strainer e um funil, coe para uma garrafa."]', '200', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-alfazema.jpg'),
(9, 'Xarope de Amora', '', '[{"name":"Amoras","amount":"250","unit":"g","note":""},{"name":"Pimenta Jamaica","amount":"5","unit":"sementes","note":"sementes trituradas"},{"name":"Laranja","amount":"1","unit":"casca","note":"sem a parte branca"},{"name":"Água","amount":"200","unit":"ml","note":""},{"name":"Açúcar","amount":"200","unit":"g","note":""}]', '["Dar uma leve macerada nas amoras, em fogo médio, colocar primeiro a água depois, a casca de laranja, as sementes Jamaica, as amoras e no final o açúcar. Dê uma quebradinha nas amoras, e incorpore o açúcar.","Mexer até diluir o açúcar, quando começar a fervura colocar o fogo entre o médio e baixo, deixar por 5 a 8 minutos. Esperar esfriar, coar com peneira bem fina e depois colocar na garrafa."]', '200', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-amora.jpg'),
(10, 'Xarope de Banana', '', '[{"name":"Banana Prata","amount":"200","unit":"g","note":""},{"name":"Canela","amount":"30","unit":"g","note":""},{"name":"Cravo","amount":"10","unit":"g","note":""},{"name":"Xarope de Açúcar","amount":"650","unit":"ml","note":""},{"name":"Água","amount":"250","unit":"ml","note":""}]', '["Mesma forma de preparo do Xarope de Frutas Vermelhas. Coloque em uma garrafa bem fechada e mantenha-os na geladeira (assim ela durará mais tempo e evitará que chame formiga)."]', '800', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-banana.jpg'),
(11, 'Xarope de Baunilha', '', '[{"name":"Açúcar Demerara","amount":"2","unit":"xícaras","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""},{"name":"Extrato de Baunilha","amount":"3","unit":"colgeres","note":"colheres de chá, se for usar essência são 6 colheres de chá"}]', '["Método: Infusão / Maceração","Em uma panela, com fogo médio, adicione o açúcar e a água. Dissolva bem. Depois, vai mexendo sempre. Coloque as colheres de extrato de baunilha e deixe no fogo por 10 minutos. Deixe resfriar e depois envase."]', '340', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-baunilha.jpg'),
(12, 'Xarope de Beterraba', '', '[{"name":"Beterrabas","amount":"6-8","unit":"unidades","note":"beterrabas médias e sem casca"},{"name":"Açúcar","amount":"720","unit":"g","note":""},{"name":"Água","amount":"","unit":" ","note":"para cobrir a mistura"}]', '["Em uma panela, adicione as beterrabas cortadas em cubos e o açúcar. Em seguida, coloque água suficiente para cobrir a mistura. Cozinhe em fogo médio durante 30 minutos ou até que os pedaços estejam ligeiramente macios. Tire do fogo e coe com um tea strainer para uma garrafa."]', '500', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-beterraba.jpg'),
(13, 'Xarope de Caju', '', '[{"name":"Açúcar","amount":"1","unit":"kg","note":""},{"name":"Água","amount":"500","unit":"ml","note":""},{"name":"Suco de Caju","amount":"500","unit":"ml","note":""},{"name":"Chá de Caldo de Limão","amount":"240","unit":"ml","note":"ou 4 colheres de sopa"}]', '["Espremer os cajus com as mãos limpas; juntar um pouco de caldo de Limão; medir a quantidade de suco obtida; medir uma porção de açúcar correspondente ao dobro do suco de caju obtido;","Fazer uma calda grossa com açúcar e água; adicionar o suco e mexer com uma colher de pau; levar o preparo ao fogo; retirar do fogo logo que levantar fervura; tirar a espuma e deixar repousar um pouco;","Passar o xarope no coador de pano fino; engarrafar ainda quente e arrolhar a garrafa depois de frio."]', '1000', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-caju.png'),
(14, 'Xarope de Camomila', '', '[{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Açúcar Demerara","amount":"240","unit":"g","note":""},{"name":"Chá de Camomila","amount":"4","unit":"colheres","note":"medida são colheres de sopa"}]', '["Método: Infusão","Junte o açúcar e a água em uma panela em fogo alto e misture até que o açúcar se dissolva. Faça a a infusão do chá por 20 minutos e coe com um tea strainer e um funil para uma garrafa. deixe esfriar, tampe e armazene na geladeira."]', '250', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-camomila.jpg'),
(15, 'Xarope de Canela', '', '[{"name":"Açúcar","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Canela em Pau","amount":"4","unit":"unidades","note":"quebrar em pedaços menores"}]', '["Método: Infusão/decocção","Em uma panela, aqueça todos ingredientes em fogo médio. Chegando ao ponto de fervura, reduza para fogo baixo e mantenha entre 8 e 10 minutos, mexendo constantemente até que o açúcar dissolva por completo. Tire do fogo e coe para uma garrafa, removendo também os pedaços de canela."]', '250', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-canela.jpg'),
(16, 'Xarope de Cardamomo', '', '[{"name":"Açúcar","amount":"2","unit":"xícaras","note":""},{"name":"Água","amount":"2","unit":"xícaras","note":""},{"name":"Vagens de Cardamomo negro","amount":"6","unit":"vagens","note":"ou substitua por 3 gotas de essência de cardamomo negro"}]', '["Método: Infusão","Junte todos os ingredientes em uma panela em fogo médio e misture até que o açúcar se dissolva. Deixe esfriar e coe com um tea strainer e um funil para uma garrafa."]', '360', '', '60 dias', '/uploads/syrups/xarope-cardamomo.jpg'),
(17, 'Xarope de Cereja', '', '[{"name":"Glicerina","amount":"30","unit":"ml","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Bagaços de Cereja","amount":"30","unit":"ml","note":""},{"name":"Suco de Cereja","amount":"120","unit":"ml","note":"suco fresco"},{"name":"Açúcar","amount":"300","unit":"ml","note":""}]', '["Método: Maceração/Infusão","Misture a glicerina com 120 ml de água e o bagaço de cerejeira e deixe descansar por 24 horas. Coe a mistura para uma garrafa. Agora cubra os mesmos bagaços com 120 ml de água quente e deixe descansar por 1 hora. Coe este líquido para a mesma garrafa do primeiro passo. Adicione o suco de cereja até completar 350 ml de líquido e, em seguida, complete com o açúcar e mexa até ser totalmente dissolvido."]', '300', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-cereja.jpg'),
(18, 'Xarope de Cerveja Pilsen', '', '[{"name":"Cerveja Pilsen","amount":"500","unit":"ml","note":""},{"name":"Açúcar","amount":"300","unit":"ml","note":""}]', '["Ferver em fogo baixo a cerveja e acrescentar o açúcar. Mexer até dissolver. Deixar ferver por 15 minutos, até atingir o ponto de xarope. Deixar esfriar e passar para um frasco esterilizado."]', '500', 'Refrigeração', '20 dias', '/uploads/syrups/xarope-cerveja.jpg'),
(19, 'XAROPE DE CEVADA', '', '[{"name":"Açúcar","amount":"2","unit":"xícaras","note":""},{"name":"Água","amount":"2","unit":"xícaras","note":""},{"name":"Cevada Torrada e Moída","amount":"1","unit":"colheres","note":"colheres de sopa cheias"}]', '["Método: infusão","Em uma panela, junte a cevada e a água e aqueça em fogo médio, até atingir o ponto de fervura. Tire do fogo e passe a mistura por um filtro de papel. Retorne o líquido para a panela e acrescente o açúcar, mexendo até dissolvê-lo por completo. Desligue o fogo e deixe esfriar. Coe para uma garrafa e armazene na geladeira."]', '350', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-cevada.jpg'),
(20, 'Xarope de Chocolate', '', '[{"name":"Cacau em Pó","amount":"30","unit":"g","note":"sem açúcar o cacau"},{"name":"Açúcar","amount":"3","unit":"xícaras","note":""},{"name":"Água","amount":"2","unit":"xícaras","note":""},{"name":"Extrato de Baunilha","amount":"3/4","unit":"colher","note":"colher de sopa como medida"},{"name":"Óleo de Canela","amount":"1","unit":"gota","note":"opcional"}]', '["Método: decocção","Em uma panela, junte o cacau em pó, o açúcar e a água e coloque no fogo médio, sempre misturando. Após levantar fervura, misture por mais três minutos. Desligue e deixe esfriar. Adicione o extrato de baunilha e o óleo de canela. Misture e engarrafe sem coar. Tampe e guarde na geladeira."]', '350', 'Refrigeração', '30 dias', '/uploads/syrups/xarope-chocolate.jpg'),
(21, 'Xarope de Cravo da Índia', '', '[{"name":"Açúcar Demerara","amount":"240","unit":"g","note":""},{"name":"Água","amount":"240","unit":"ml","note":""},{"name":"Cravos da Índia","amount":"1/3","unit":"xícara","note":""}]', '["Método: Infusão","Em uma panela, junte todos os ingredientes e aqueça em fogo médio, sempre mexendo. Pouco antes do ponto de fervura, reduza para o fogo baixo e deixe cozinhando por 20 minutos, mexendo de vez em quando. Desligue o fogo e deixe esfriar. Em seguida, coe com o tea strainer e um funil para uma garrafa. Tampe e armazene sob refrigeração."]', '240', 'Refrigeração', '2 semanas', '/uploads/syrups/xarope-cravo.jpg'),
(22, 'Xarope de 5 Especiarias', '', '[{"name":"Açúcar","amount":"1/2","unit":"xícara","note":""},{"name":"Água","amount":"1","unit":"xícara","note":""},{"name":"Mel","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Anis Estrelado","amount":"2","unit":"colheres","note":"colher de sopa"},{"name":"Semente de Funcho","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Pimenta-de-Sichuan","amount":"1","unit":"colher","note":"colher de sopa"},{"name":"Cravos da Índia","amount":"1/2","unit":"colher","note":"colher de sopa"},{"name":"Canela em Pau","amount":"1","unit":"unidade","note":"quebrada em pedaços pequenos"}]', '["Adicione as especiarias em uma panela em fogo médio até que liberem os aromas, em cerca de 3 ou 4 minutos. Adicione, em seguida, o restante dos ingredientes. Após o ponto de fervura, cozinhe por 5 minutos. Desligue o fogo e deixe esfriar. Coe para uma garrafa, tampe e guarde na geladeira."]', '250', 'Refrigeração', '2 semanas', '')
